"use client";
import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { createClient } from "@/lib/supabase/client";
import { getCurrentUserProfile, signOutUser } from "@/lib/auth";

export default function VendorDashboard() {
 const router=useRouter(); const [vendor,setVendor]=useState(null); const [packages,setPackages]=useState([]); const [reviews,setReviews]=useState([]); const [error,setError]=useState(""); const [loading,setLoading]=useState(true);
 useEffect(()=>{ (async()=>{ try { const account=await getCurrentUserProfile(); if(account?.profile?.role!=="vendor"){router.replace("/auth/login");return;} const db=createClient(); if(!db) throw new Error("Supabase is not configured."); const v=await db.from("vendors").select("*").eq("owner_user_id",account.user.id).single(); if(v.error) throw new Error("No vendor profile is linked. Contact Admin."); setVendor(v.data); const p=await db.from("food_packages").select("id,package_name,category,price,status,created_at").eq("vendor_id",v.data.id).order("created_at",{ascending:false}); if(p.error) throw p.error; setPackages(p.data||[]); const ids=(p.data||[]).map(x=>x.id); if(ids.length){const f=await db.from("feedback").select("id,package_id,rating,comment,created_at").in("package_id",ids).order("created_at",{ascending:false}); if(f.error) throw f.error; setReviews(f.data||[]);} } catch(e){setError(e.message||"Unable to load dashboard.");} finally{setLoading(false);} })(); },[router]);
 async function toggle(item){const db=createClient();const status=item.status==="active"?"inactive":"active";const r=await db.from("food_packages").update({status}).eq("id",item.id);if(r.error){setError(r.error.message);return;}setPackages(old=>old.map(x=>x.id===item.id?{...x,status}:x));}
 async function logout(){await signOutUser();router.replace("/auth/login");}
 const avg=reviews.length?(reviews.reduce((s,x)=>s+x.rating,0)/reviews.length).toFixed(1):"—";
 return <main style={{minHeight:"100vh",background:"#f3f6fb",color:"#17243a",fontFamily:"Arial,sans-serif"}}><header style={{background:"#10233f",color:"white",padding:"24px 5%",display:"flex",justifyContent:"space-between",alignItems:"center"}}><div><small>RAILGUARD · VENDOR PORTAL</small><h1 style={{margin:"6px 0"}}>Catering Partner Dashboard</h1></div><button onClick={logout}>Sign out</button></header><section style={{maxWidth:1100,margin:"auto",padding:24}}>{loading?"Loading dashboard…":error?<p role="alert">{error}</p>:<><h2>{vendor?.business_name}</h2><p>{vendor?.station_location} · Licence {vendor?.license_number}</p><div style={{display:"flex",gap:16,flexWrap:"wrap"}}>{[["Food packages",packages.length],["Reviews",reviews.length],["Average rating",avg]].map(([k,v])=><article key={k} style={{background:"white",padding:22,borderRadius:12,minWidth:170}}><small>{k}</small><h2>{v}</h2></article>)}</div><h2>Your food packages</h2>{packages.length===0?<p>No packages assigned yet. Contact RailGuard Admin.</p>:packages.map(p=><article key={p.id} style={{background:"white",padding:16,marginBottom:10,borderRadius:10,display:"flex",justifyContent:"space-between",gap:12}}><div><b>{p.package_name}</b><p>{p.category||"Meal"} · {p.price==null?"Price not set":"₹"+p.price} · {p.status}</p></div><button onClick={()=>toggle(p)}>{p.status==="active"?"Deactivate":"Activate"}</button></article>)}<h2>Passenger feedback</h2>{reviews.length===0?<p>No reviews yet.</p>:reviews.map(f=><article key={f.id} style={{background:"white",padding:14,marginBottom:8,borderRadius:8}}><b>{"★".repeat(f.rating)}{"☆".repeat(5-f.rating)}</b><p>{f.comment||"Rating only"}</p><small>{new Date(f.created_at).toLocaleString()}</small></article>)}<p style={{color:"#68778d",fontSize:13}}>Vendors can manage only their own packages and view their own feedback. Complaint assignment, inspection reports and complaint closure remain under Railway Admin control.</p></>}</section></main>;
}
